function auth_post(string $path): void { verify_csrf(); $email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??''); if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){flash('error','Enter a valid email and a password of at least 8 characters.');redirect($path);} if($path==='/register'){ $name=trim((string)($_POST['name']??''));if(mb_strlen($name)<2){flash('error','Enter your full name.');redirect('/register');} try{$s=db()->prepare('INSERT INTO users (name,email,password,plan,created_at) VALUES (?,?,?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),'free',date('Y-m-d H:i:s')]);$_SESSION['user_id']=(int)db()->lastInsertId();flash('success','Welcome to Clyp. Your studio is ready.');redirect('/dashboard');}catch(PDOException $e){flash('error','An account with that email already exists.');redirect('/register');}} $s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($password,$u['password'])){flash('error','Email or password is incorrect.');redirect('/login');}session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];redirect('/dashboard'); }
