<div class="dashboard-welcome"><div><p>Welcome back, <?=e(explode(' ',$u['name'])[0])?></p><h2>What are we publishing today?</h2></div><a class="btn btn-primary" href="/upload"><?=icon('plus')?> New project</a></div><div class="stat-grid"><article><span>Projects</span><strong><?=count($projects)?></strong><small>All time</small></article><article><span>Exports this month</span><strong><?=$usage?><?=$plan['exports']>0?' / '.$plan['exports']:''?></strong><small><?=e($plan['name'])?> plan</small></article><article><span>Studio status</span><strong class="online">Ready</strong><small>Auto-edit pipeline</small></article></div><div class="section-row"><div><p class="eyebrow">YOUR WORK</p><h2>Recent projects</h2></div></div><?php if($projects):?><div class="project-grid"><?php foreach($projects as $p)echo project_card($p);?></div><?php else:?><div class="empty-state"><div><?=icon('video','w-9 h-9')?></div><h3>Your first Clyp starts here</h3><p>Upload a video and let Clyp build the complete first edit automatically.</p><a class="btn btn-primary" href="/upload"><?=icon('upload')?> Upload video</a></div><?php endif;?>
