function render_content_cards(array $c): string { $labels=['hook'=>'Hook','title'=>'Video title','instagram'=>'Instagram caption','whatsapp'=>'WhatsApp status','facebook'=>'Facebook post','x'=>'X post','hashtags'=>'Hashtags'];ob_start();foreach($labels as $key=>$label){$value=$c[$key]??'';if(is_array($value))$value=implode(' ',$value);?><article><div><span><?=e($label)?></span><button data-copy><?=icon('copy','w-4 h-4')?></button></div><textarea readonly rows="<?=$key==='instagram'||$key==='facebook'?5:3?>"><?=e((string)$value)?></textarea></article><?php }return (string)ob_get_clean(); }
function serve_media(): never { $u=require_auth();$type=(string)($_GET['type']??'');$id=(int)($_GET['id']??0);$file='';$download=false;if($type==='video'){$s=db()->prepare('SELECT video_file,original_name FROM projects WHERE id=? AND user_id=?');$s->execute([$id,(int)$u['id']]);$r=$s->fetch();$file=$r?BASE_PATH.'/'.$r['video_file']:'';}elseif($type==='export'){$s=db()->prepare('SELECT e.export_url FROM exports e JOIN projects p ON p.id=e.project_id WHERE e.id=? AND p.user_id=?');$s->execute([$id,(int)$u['id']]);$r=$s->fetch();$file=$r?BASE_PATH.'/'.$r['export_url']:'';$download=true;}elseif($type==='sound'){$s=db()->prepare('SELECT file_path FROM sounds WHERE id=?');$s->execute([$id]);$r=$s->fetch();$file=$r?BASE_PATH.'/'.$r['file_path']:'';}if(!$file||!is_file($file)){http_response_code(404);exit('File not found');}$mime=mime_content_type($file)?:'application/octet-stream';$size=filesize($file);header('Content-Type: '.$mime);header('Accept-Ranges: bytes');if($download)header('Content-Disposition: attachment; filename="'.basename($file).'"');$start=0;$end=$size-1;if(isset($_SERVER['HTTP_RANGE'])&&preg_match('/bytes=(\d*)-(\d*)/',$_SERVER['HTTP_RANGE'],$m)){$start=$m[1]!==''?(int)$m[1]:0;$end=$m[2]!==''?(int)$m[2]:$end;$end=min($end,$size-1);http_response_code(206);header("Content-Range: bytes $start-$end/$size");}header('Content-Length: '.($end-$start+1));$fh=fopen($file,'rb');fseek($fh,$start);$left=$end-$start+1;while($left>0&&!feof($fh)){$chunk=fread($fh,min(8192,$left));echo $chunk;$left-=strlen($chunk);flush();}fclose($fh);exit; }
function payment_callback(): never { $u=require_auth();$reference=trim((string)($_GET['reference']??''));$plan=(string)($_SESSION['pending_plan']??'');if($reference===''||!isset(plans()[$plan])){flash('error','Payment reference was missing.');redirect('/pricing');}try{$used=db()->prepare('SELECT id FROM subscriptions WHERE reference=? LIMIT 1');$used->execute([$reference]);if($used->fetchColumn())throw new RuntimeException('This payment has already been applied.');$data=(new PaystackService())->verify($reference);$expected=plans()[$plan]['amount']*100;$paidEmail=strtolower((string)($data['customer']['email']??''));$currency=strtoupper((string)($data['currency']??''));if(($data['status']??'')==='success'&&(int)($data['amount']??0)===$expected&&$paidEmail===strtolower((string)$u['email'])&&$currency===strtoupper((string)env('PAYSTACK_CURRENCY','NGN'))){db()->beginTransaction();db()->prepare('UPDATE users SET plan=? WHERE id=?')->execute([$plan,(int)$u['id']]);db()->prepare('INSERT INTO subscriptions (user_id,plan,amount,status,reference,created_at) VALUES (?,?,?,?,?,?)')->execute([(int)$u['id'],$plan,plans()[$plan]['amount'],'active',$reference,date('Y-m-d H:i:s')]);db()->commit();unset($_SESSION['pending_plan']);flash('success','Payment verified. Your plan is active.');redirect('/dashboard');}throw new RuntimeException('Payment verification did not match this account and plan.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());redirect('/pricing');} }
function not_found(): never { http_response_code(404);page_start('Page not found');?><main class="not-found"><h1>404</h1><p>This page slipped out of the timeline.</p><a class="btn btn-primary" href="/">Back to Clyp</a></main><?php page_end();exit; }
